// Fees and invoices visual baselines (#872): the list, the empty list, the agreement dialog, the
// editor with its GST banner and a final invoice with its ledger at 360, 768 and 1280 px in light
// and dark (the viewport and theme projects). Fictional records only. Baselines are generated by
// the update-visual workflow and compared in CI.
import { expect, test } from '../../fixtures/index.ts';
import { FEES } from '../../fixtures/fees-data.ts';

import { emptyTitle, invoiceRows, openFees } from './fees-helpers.ts';

const shot = { fullPage: true, animations: 'disabled' } as const;

test.describe('fees visual', { tag: '@visual' }, () => {
  test('list', async ({ page, asUser, db }) => {
    await openFees(page, asUser, db.name);
    await expect(invoiceRows(page)).toHaveCount(2);
    await expect(page).toHaveScreenshot('fees-list.png', shot);
  });

  test('empty', async ({ page, asUser, db }) => {
    await openFees(page, asUser, db.name, { agreement: false, draft: false, issued: false });
    await expect(emptyTitle(page, 'No invoices yet')).toBeVisible();
    await expect(page).toHaveScreenshot('fees-empty.png', shot);
  });

  test('agreement dialog', async ({ page, asUser, db }) => {
    await openFees(page, asUser, db.name);
    await page
      .getByRole('button', { name: 'New fee agreement' })
      .filter({ visible: true })
      .first()
      .click();
    await expect(page.getByRole('dialog', { name: 'New fee agreement' })).toBeVisible();
    await expect(page).toHaveScreenshot('fees-agreement-dialog.png', { animations: 'disabled' });
  });

  test('editor with the GST banner', async ({ page, asUser, db }) => {
    await openFees(page, asUser, db.name, { path: `invoices/${FEES.draft.id}` });
    const form = page.getByRole('form', { name: 'Draft invoice' });
    await form.getByLabel('Your state code').fill(FEES.stateCode);
    await form.getByRole('button', { name: 'Preview' }).click();
    await expect(
      page.locator('[data-slot="fees-gst-banner"]').filter({ visible: true }),
    ).toBeVisible();
    await expect(page).toHaveScreenshot('fees-editor-preview.png', shot);
  });

  test('final invoice with the ledger', async ({ page, asUser, db }) => {
    await openFees(page, asUser, db.name, { path: `invoices/${FEES.issued.id}` });
    await expect(page.getByText('This invoice is final.')).toBeVisible();
    await expect(
      page.locator('[data-slot="ledger-balance"]').filter({ visible: true }),
    ).toBeVisible();
    await expect(page).toHaveScreenshot('fees-final-invoice.png', shot);
  });
});
